import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64

.visible .entry bn2d_fwd(
    .param .u64 x_ptr,
    .param .u64 out_ptr,
    .param .u64 w_ptr,
    .param .u64 b_ptr,
    .param .u64 rm_ptr,
    .param .u64 rv_ptr,
    .param .u64 nbt_ptr,
    .param .u32 n_in,
    .param .u32 c_in,
    .param .u32 hw_in,
    .param .u32 train_in,
    .param .f32 eps_in,
    .param .f32 mom_in
)
{
    .reg .u32 %tx, %ch, %n, %c, %hw, %train, %b, %i, %s, %src, %off32, %src32, %sa, %sb;
    .reg .u64 %x, %out, %wp, %bp, %rmp, %rvp, %nbt, %ch64, %b64, %c64, %hw64, %i64, %off, %base, %addr, %oaddr, %taddr, %n64, %nm1, %src64, %tid64;
    .reg .s64 %nb;
    .reg .f32 %eps, %mom, %gamma, %beta, %mean, %inv, %var, %xf, %yf, %one, %onem, %old, %new, %den, %t1, %unb;
    .reg .f64 %sum, %sq, %val, %prod, %mean64, %ssc, %var64, %den64, %dnm1, %varun64, %a64, %dtmp;
    .reg .pred %p, %q, %r;
    .shared .align 8 .f64 sh_sum[256];
    .shared .align 8 .f64 sh_sq[256];
    .shared .align 4 .f32 sh_stats[2];

    ld.param.u64 %x, [x_ptr];
    ld.param.u64 %out, [out_ptr];
    ld.param.u64 %wp, [w_ptr];
    ld.param.u64 %bp, [b_ptr];
    ld.param.u64 %rmp, [rm_ptr];
    ld.param.u64 %rvp, [rv_ptr];
    ld.param.u64 %nbt, [nbt_ptr];
    ld.param.u32 %n, [n_in];
    ld.param.u32 %c, [c_in];
    ld.param.u32 %hw, [hw_in];
    ld.param.u32 %train, [train_in];
    ld.param.f32 %eps, [eps_in];
    ld.param.f32 %mom, [mom_in];

    mov.u32 %tx, %tid.x;
    mov.u32 %ch, %ctaid.x;
    cvt.u64.u32 %ch64, %ch;
    shl.b64 %off, %ch64, 2;
    add.u64 %addr, %wp, %off;
    ld.global.f32 %gamma, [%addr];
    add.u64 %addr, %bp, %off;
    ld.global.f32 %beta, [%addr];
    mov.f32 %one, 0f3F800000;

    setp.eq.u32 %p, %train, 0;
    @%p bra EVAL;

    mov.f64 %sum, 0d0000000000000000;
    mov.f64 %sq, 0d0000000000000000;
    cvt.u64.u32 %c64, %c;
    cvt.u64.u32 %hw64, %hw;
    mov.u32 %b, 0;
TB_LOOP:
    setp.lt.u32 %p, %b, %n;
    @!%p bra REDUCE;
    cvt.u64.u32 %b64, %b;
    mul.lo.u64 %base, %b64, %c64;
    add.u64 %base, %base, %ch64;
    mul.lo.u64 %base, %base, %hw64;
    shl.b64 %base, %base, 2;
    add.u64 %base, %x, %base;
    mov.u32 %i, %tx;
TI_LOOP:
    setp.lt.u32 %q, %i, %hw;
    @!%q bra TB_NEXT;
    cvt.u64.u32 %i64, %i;
    shl.b64 %off, %i64, 2;
    add.u64 %taddr, %base, %off;
    ld.global.f32 %xf, [%taddr];
    cvt.f64.f32 %val, %xf;
    add.f64 %sum, %sum, %val;
    mul.f64 %dtmp, %val, %val;
    add.f64 %sq, %sq, %dtmp;
    add.u32 %i, %i, 256;
    bra TI_LOOP;
TB_NEXT:
    add.u32 %b, %b, 1;
    bra TB_LOOP;

REDUCE:
    mul.lo.u32 %off32, %tx, 8;
    mov.u32 %sa, sh_sum;
    add.u32 %sa, %sa, %off32;
    mov.u32 %sb, sh_sq;
    add.u32 %sb, %sb, %off32;
    st.shared.f64 [%sa], %sum;
    st.shared.f64 [%sb], %sq;
    bar.sync 0;
    mov.u32 %s, 128;
RED_LOOP:
    setp.eq.u32 %p, %s, 0;
    @%p bra RED_DONE;
    setp.lt.u32 %q, %tx, %s;
    @!%q bra RED_WAIT;
    add.u32 %src, %tx, %s;
    mul.lo.u32 %src32, %src, 8;
    mov.u32 %sa, sh_sum;
    add.u32 %sa, %sa, %src32;
    mov.u32 %sb, sh_sq;
    add.u32 %sb, %sb, %src32;
    ld.shared.f64 %a64, [%sa];
    ld.shared.f64 %dtmp, [%sb];
    add.f64 %sum, %sum, %a64;
    add.f64 %sq, %sq, %dtmp;
    mul.lo.u32 %off32, %tx, 8;
    mov.u32 %sa, sh_sum;
    add.u32 %sa, %sa, %off32;
    mov.u32 %sb, sh_sq;
    add.u32 %sb, %sb, %off32;
    st.shared.f64 [%sa], %sum;
    st.shared.f64 [%sb], %sq;
RED_WAIT:
    bar.sync 0;
    shr.u32 %s, %s, 1;
    bra RED_LOOP;
RED_DONE:
    setp.ne.u32 %p, %tx, 0;
    @%p bra T_WAIT;
    ld.shared.f64 %sum, [sh_sum];
    ld.shared.f64 %sq, [sh_sq];
    cvt.u64.u32 %n64, %n;
    cvt.u64.u32 %hw64, %hw;
    mul.lo.u64 %n64, %n64, %hw64;
    cvt.rn.f64.u64 %den64, %n64;
    div.rn.f64 %mean64, %sum, %den64;
    mul.f64 %prod, %sum, %sum;
    div.rn.f64 %prod, %prod, %den64;
    sub.f64 %ssc, %sq, %prod;
    div.rn.f64 %var64, %ssc, %den64;
    cvt.rn.f32.f64 %mean, %mean64;
    cvt.rn.f32.f64 %var, %var64;
    add.f32 %den, %var, %eps;
    sqrt.rn.f32 %den, %den;
    div.rn.f32 %inv, %one, %den;
    st.shared.f32 [sh_stats], %mean;
    st.shared.f32 [sh_stats + 4], %inv;
    setp.le.u64 %p, %n64, 1;
    @%p bra UNB_BIASED;
    sub.u64 %nm1, %n64, 1;
    cvt.rn.f64.u64 %dnm1, %nm1;
    div.rn.f64 %varun64, %ssc, %dnm1;
    bra UNB_DONE;
UNB_BIASED:
    mov.f64 %varun64, %var64;
UNB_DONE:
    cvt.rn.f32.f64 %unb, %varun64;
    sub.f32 %onem, %one, %mom;
    shl.b64 %off, %ch64, 2;
    add.u64 %addr, %rmp, %off;
    ld.global.f32 %old, [%addr];
    mul.f32 %t1, %onem, %old;
    fma.rn.f32 %new, %mom, %mean, %t1;
    st.global.f32 [%addr], %new;
    add.u64 %addr, %rvp, %off;
    ld.global.f32 %old, [%addr];
    mul.f32 %t1, %onem, %old;
    fma.rn.f32 %new, %mom, %unb, %t1;
    st.global.f32 [%addr], %new;
    setp.eq.u32 %r, %ch, 0;
    @!%r bra T_WAIT;
    ld.global.s64 %nb, [%nbt];
    add.s64 %nb, %nb, 1;
    st.global.s64 [%nbt], %nb;
T_WAIT:
    bar.sync 0;
    ld.shared.f32 %mean, [sh_stats];
    ld.shared.f32 %inv, [sh_stats + 4];
    bra NORM;

EVAL:
    setp.ne.u32 %p, %tx, 0;
    @%p bra E_WAIT;
    shl.b64 %off, %ch64, 2;
    add.u64 %addr, %rmp, %off;
    ld.global.f32 %mean, [%addr];
    add.u64 %addr, %rvp, %off;
    ld.global.f32 %var, [%addr];
    add.f32 %den, %var, %eps;
    sqrt.rn.f32 %den, %den;
    div.rn.f32 %inv, %one, %den;
    st.shared.f32 [sh_stats], %mean;
    st.shared.f32 [sh_stats + 4], %inv;
E_WAIT:
    bar.sync 0;
    ld.shared.f32 %mean, [sh_stats];
    ld.shared.f32 %inv, [sh_stats + 4];

NORM:
    cvt.u64.u32 %c64, %c;
    cvt.u64.u32 %hw64, %hw;
    mov.u32 %b, 0;
NB_LOOP:
    setp.lt.u32 %p, %b, %n;
    @!%p bra DONE;
    cvt.u64.u32 %b64, %b;
    mul.lo.u64 %base, %b64, %c64;
    add.u64 %base, %base, %ch64;
    mul.lo.u64 %base, %base, %hw64;
    shl.b64 %base, %base, 2;
    add.u64 %addr, %x, %base;
    add.u64 %oaddr, %out, %base;
    mov.u32 %i, %tx;
NI_LOOP:
    setp.lt.u32 %q, %i, %hw;
    @!%q bra NB_NEXT;
    cvt.u64.u32 %i64, %i;
    shl.b64 %off, %i64, 2;
    add.u64 %taddr, %addr, %off;
    ld.global.f32 %xf, [%taddr];
    sub.f32 %yf, %xf, %mean;
    mul.f32 %yf, %yf, %inv;
    fma.rn.f32 %yf, %yf, %gamma, %beta;
    add.u64 %taddr, %oaddr, %off;
    st.global.f32 [%taddr], %yf;
    add.u32 %i, %i, 256;
    bra NI_LOOP;
NB_NEXT:
    add.u32 %b, %b, 1;
    bra NB_LOOP;
DONE:
    ret;
}
