_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    _get_ptx_module().function("bn2d_fwd")

class ModelNew(nn.Module):
    def __init__(self, num_features: int):
        super().__init__()
        self.num_features = num_features
        self.eps = 1e-5
        self.momentum = 0.1
        self.affine = True
        self.track_running_stats = True
        self.weight = nn.Parameter(torch.tensor([1.0] * num_features, dtype=torch.float32))
        self.bias = nn.Parameter(torch.tensor([0.0] * num_features, dtype=torch.float32))
        self.register_buffer("running_mean", torch.tensor([0.0] * num_features, dtype=torch.float32))
        self.register_buffer("running_var", torch.tensor([1.0] * num_features, dtype=torch.float32))
        self.register_buffer("num_batches_tracked", torch.tensor(0, dtype=torch.int64))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if x.dim() != 4:
            raise ValueError("expected 4D input")
        if x.dtype != torch.float32:
            raise TypeError("expected float32 input")
        n, c, d1, d2 = x.shape
        if c != self.num_features:
            raise ValueError("feature mismatch")
        if not x.is_contiguous():
            raise ValueError("expected contiguous NCHW input")
        out = torch.empty((n, c, d1, d2), device=x.device, dtype=x.dtype)
        module = _get_ptx_module()
        module.launch(
            "bn2d_fwd",
            grid=(c, 1, 1),
            block=(256, 1, 1),
            arguments=[
                x,
                out,
                self.weight,
                self.bias,
                self.running_mean,
                self.running_var,
                self.num_batches_tracked,
                i32(n),
                i32(c),
                i32(d1 * d2),
                i32(1 if self.training else 0),
                f32(self.eps),
                f32(self.momentum),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out
